## Single Responsibility Principle (SRP)

## Definition

> A class should have only one reason to change.

'Reason to change' = the business actor or concern that drives the change.

## Violation Example

```typescript
// ❌ UserReport has THREE reasons to change:
//    1. Accounting changes how salary is calculated
//    2. HR changes the report format
//    3. DBA changes the save format
class UserReport {
  calculatePay(user: User): number { /* accounting logic */ }
  renderHTML(user: User): string { /* formatting logic */ }
  saveToDatabase(user: User): void { /* persistence logic */ }
}
```

## Fixed

```typescript
// Each class has one responsibility
class PayrollCalculator {
  calculate(user: User): number { /* only accounting rules here */ }
}

class UserReportRenderer {
  renderHTML(user: User, pay: number): string { /* only formatting */ }
}

class UserRepository {
  save(user: User): Promise<void> { /* only persistence */ }
}
```

## In React Components

```typescript
// ❌ One component doing too many things
function UserProfile({ userId }: { userId: string }) {
  const [user, setUser] = useState(null);
  const [posts, setPosts] = useState([]);

  useEffect(() => { /* fetch user */ }, []);
  useEffect(() => { /* fetch posts */ }, []);

  // transforms data
  // renders profile
  // renders posts
  // handles edit form
  // handles delete
}

// ✅ Split responsibilities
function UserProfile({ userId }: { userId: string }) {
  const { user } = useUser(userId);      // data concern in custom hook
  const { posts } = useUserPosts(userId);
  return <UserProfileView user={user} posts={posts} />;
}

function UserProfileView({ user, posts }) {
  return ( /* pure render, no data fetching */ );
}
```

