## Eşleme Zinciri

```
[Veritabanı / Domain Katmanı]
      ↓
  Domain Entity  (zengin, davranışı var, invariant'ları zorlar)
      ↓  Application Service eşler
    DTO          (düz veri transferi, davranış yok)
      ↓  Sunum katmanı eşler
  ViewModel      (UI'ı beslemek için şekillendirilmiş)
```

## DTO — Veri Transfer Nesnesi

```typescript
// Katmanlar arasında veri taşır — davranış yok
export interface UserDTO {
  id: string;
  email: string;
  name: string;
  createdAt: string; // ISO string — domain Date değil
}

// Application Service içinde:
function toDTO(user: User): UserDTO {
  return {
    id: user.id.value,
    email: user.email.value,
    name: user.name,
    createdAt: user.createdAt.toISOString(),
  };
}
```

## ViewModel — UI'a Özgü Şekillendirme

```typescript
// DTO'yu UI ihtiyaçlarına dönüştür
export interface UserProfileViewModel {
  displayName: string;      // 'Aaron K.' gibi biçimlendirilmiş
  initials: string;         // avatar için 'AK'
  joinedLabel: string;      // 'Mayıs 2024'te katıldı'
  isVerified: boolean;
}

function toViewModel(dto: UserDTO): UserProfileViewModel {
  return {
    displayName: formatDisplayName(dto.name),
    initials: getInitials(dto.name),
    joinedLabel: `${format(new Date(dto.createdAt), 'MMMM yyyy')}'da katıldı`,
    isVerified: dto.emailVerified,
  };
}
```

